BX.ready((()=>{const e=document.querySelector("body"),t=new TinyGesture(e,{velocityThreshold:8,disregardVelocityThreshold:()=>80});t.on("swiperight",(e=>{if(e.target.closest(".section-gallery-wrapper")){const t=e.target.closest(".image_wrapper_block"),r=t.querySelector(".section-gallery-wrapper__item._active"),s=t.querySelector(".section-gallery-wrapper").lastElementChild,l=r.previousElementSibling;r.classList.remove("_active"),l?l.classList.add("_active"):s.classList.add("_active")}})),t.on("swipeleft",(e=>{if(e.target.closest(".section-gallery-wrapper")){const t=e.target.closest(".image_wrapper_block"),r=t.querySelector(".section-gallery-wrapper__item._active"),s=t.querySelector(".section-gallery-wrapper").firstElementChild,l=r.nextElementSibling;r.classList.remove("_active"),l?l.classList.add("_active"):s.classList.add("_active")}})),t.on("swipeup",(e=>{}))}));